<?php
declare(strict_types=1);
ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/collab/core.php';require dirname(__DIR__).'/private/collab/files.php';require dirname(__DIR__).'/private/collab/documents.php';
security_headers();header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex,nofollow');
try{
 $a=cc_actor(($_GET['mode']??'customer')!=='owner');$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);if(!$id||$id<1)crm_fail(404,'Версия не найдена.');$r=cc_revision($a,$id);$p=cc_project($a,(int)$r['document']['project_id']);$customer=crm_record('customers',(int)$p['customer_id']);
 $e=fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
 $labels=['title'=>'Название','service'=>'Услуга','description'=>'Описание проекта','goal'=>'Бизнес-цель','requirements'=>'Требования','functionality'=>'Функциональность','design'=>'Дизайн','constraints'=>'Технические ограничения','deliverables'=>'Результаты','milestones'=>'Этапы','deadline'=>'Целевые сроки','acceptance'=>'Критерии приёмки','comments'=>'Комментарии'];
 $states=['draft'=>'Черновик','ready'=>'Готов к отправке','sent'=>'На согласовании','approved'=>'Согласован','changes_requested'=>'Требуется доработка','finalized'=>'Завершён'];
 header('Content-Type: text/html; charset=utf-8');
}catch(CrmFailure $ex){fail($ex->status,$ex->getMessage(),'collaboration_error');}catch(CustomerFailure $ex){fail($ex->status,$ex->getMessage(),$ex->errorCode);}catch(Throwable $ex){server_error($ex);}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($r['fields']['title']) ?></title><link rel="stylesheet" href="operations.css"><link rel="stylesheet" href="collaboration.css"></head><body><main class="portal print-document"><h1>НейроДело — <?= $e($r['fields']['title']) ?></h1><p>Клиент: <?= $e($customer['name']) ?> · Проект: <?= $e($p['title']) ?></p><p>Редакция <?= $e($r['revision_number']) ?> · Создана <?= $e($r['created_at']) ?> UTC · <?= $e($states[$r['status']]) ?></p><p>SHA-256: <?= $e($r['checksum']) ?></p><?php foreach($r['fields'] as $k=>$v): ?><section><h2><?= $e($labels[$k]) ?></h2><div class="document-body"><?= $e($v) ?></div></section><?php endforeach; ?><?php if(isset($r['decision'])): ?><p>Решение клиента: <?= $e($states[$r['decision']['decision']]) ?> · <?= $e($r['decision']['created_at']) ?> UTC</p><p class="document-body"><?= $e($r['decision']['feedback']) ?></p><?php endif; ?><p>Согласование в кабинете не является оплатой или заявлением о юридически значимой электронной подписи.</p><button id="print-document">Печать</button></main><script src="collab-print.js"></script></body></html>
